import{_ as t,o as a,c as o,a5 as i}from"./chunks/framework.BfQ7H7Qx.js";const g=JSON.parse('{"title":"FR 3.4.5 — Update Agency Profile","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/03-agency-workspace/3-4-5-update-agency-profile/spec.md","filePath":"feature/srs/03-agency-workspace/3-4-5-update-agency-profile/spec.md"}'),n={name:"feature/srs/03-agency-workspace/3-4-5-update-agency-profile/spec.md"};function l(r,e,s,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-4-5-—-update-agency-profile" tabindex="-1">FR 3.4.5 — Update Agency Profile <a class="header-anchor" href="#fr-3-4-5-—-update-agency-profile" aria-label="Permalink to &quot;FR 3.4.5 — Update Agency Profile&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.4.5</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-018</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">Update Agency Profile</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">Agency &amp; Workspace (<code>FR 3.4</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-15</code></td></tr><tr><td style="text-align:left;"><strong>Document Status</strong></td><td style="text-align:left;">Implemented &amp; Verified</td></tr></tbody></table><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>The Owner of an Agency opens the Agency Profile in edit mode (<code>/agencies/:agencyId/profile/edit</code>), changes one or more fields and submits the form; or uploads a new logo file while on that screen.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Owner.</li><li><strong>Purpose:</strong> Let the Owner keep the profile of the Agency up to date — its name, branding and company information.</li><li><strong>Interface:</strong> Edit Agency Profile page (<code>/agencies/:agencyId/profile/edit</code>) — the same field set as the Create Agency form, pre-filled with the current values, plus a logo picker that uploads a new logo file.</li><li><strong>Data Processing:</strong> The system loads the Agency by its identifier, confirms the caller is its Owner, validates the submitted values, and then replaces the stored profile with the submitted values in full — every field that is not sent in the request is cleared. The logo is uploaded separately, as a file, and the system fills in the logo of the Agency with the stored location.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Edit Agency Profile page:</p><ul><li>The full field set of the Agency profile, pre-filled from the current values, with the name marked as required.</li><li>A logo picker; the chosen file is uploaded separately from the form.</li><li>A save action; on success the user stays on the screen and sees the refreshed values.</li><li>Because the save replaces the whole profile, every field that must survive has to be present in the form when it is submitted.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> Name of the Agency.</li><li><strong>Input optional:</strong> logoUrl, description, category (AgencyCategory), companySize (CompanySize), website, phone, location, brandColor (hex, at most 9 characters), logoIcon, tagline (at most 140 characters), foundedYear, facebookUrl, linkedinUrl, instagramUrl. The logo file itself is sent through the separate logo upload.</li><li><strong>System data:</strong> The Agency record — id, name, ownerId, logoUrl, description, category, companySize, website, phone, location, brandColor, logoIcon, tagline, foundedYear, facebookUrl, linkedinUrl, instagramUrl, status, createdAt, updatedAt — and the Owner identifier used for the access check.</li><li><strong>Output:</strong> The updated profile of the Agency. After a logo upload, the same profile with the new logo location and a refreshed update timestamp.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-25 (analogous):</strong> Updating the Agency profile is Owner-only, mirroring the rule that workspace settings can only be updated by an authorized role (BR-25, adapted: Agency profile has a single Owner rather than OWNER/MANAGER). Anybody else is refused with <code>403 NOT_AGENCY_OWNER</code>.</li><li>The save replaces the whole profile rather than patching individual fields: a field that is not sent in the request is cleared. The client must therefore send back every current value, including the ones that did not change.</li><li>Name is mandatory; an empty name is refused with <code>400 VALIDATION_ERROR</code>.</li><li>The logo is uploaded as a file through the Agency logo upload, not through the logo URL field of the form.</li><li>A logo file that cannot be read is refused with <code>400 FILE_READ_ERROR</code> rather than an internal failure; the stored profile stays untouched in that case.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>Caller is not the Owner → Display: MSG39</li><li>Name empty → Display: MSG02</li><li>Agency does not exist → Display: MSG38</li><li>Logo upload by a caller who is not the Owner → Display: MSG39</li><li>Logo file cannot be read → Display: MSG29</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>The Owner opens the Agency Profile in edit mode; the form loads with the current values.</li><li>The Owner changes the fields that need updating and leaves the rest as they are.</li><li>The client submits the full profile.</li><li>The system loads the Agency by its identifier and confirms the caller is its Owner.</li><li>The system validates the submitted values against the rules above.</li><li>The system replaces the stored profile with the submitted values and returns the updated profile; toast MSG26.</li><li>The Owner optionally picks a new logo file; the system stores the file, fills in the logo of the Agency, and returns the updated profile; toast MSG94.</li><li>The client shows a confirmation and refreshes the form and the logo preview.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>4.a1: Agency does not exist → <code>404 AGENCY_NOT_FOUND</code>, toast MSG38. 4.a2: The Owner returns to the Agency list.</li><li>4.b1: Caller is not the Owner → <code>403 NOT_AGENCY_OWNER</code>, toast MSG39; nothing is changed. 4.b2: The caller returns to the Agency list.</li><li>5.a1: Name left empty → <code>400 VALIDATION_ERROR</code>, Display: MSG02; nothing is changed. 5.a2: The Owner fills in the name and resubmits.</li><li>7.a1: Logo file cannot be read → <code>400 FILE_READ_ERROR</code>, toast MSG29; the profile keeps its previous values. 7.a2: The Owner selects a valid file and retries the upload.</li><li>3.a1: A field that the form fails to send back is cleared, because the save replaces the whole profile — no error, this is expected behaviour. 3.a2: The Owner reviews the saved profile and re-submits any field found missing.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>The profile of the Agency carries the submitted values and a refreshed update timestamp.</li><li>After a logo upload, the Agency profile carries the new logo location and a refreshed update timestamp.</li></ul><h2 id="cross-platform-ui-i18n-theme-acceptance-criteria" tabindex="-1">Cross-Platform UI, i18n &amp; Theme Acceptance Criteria <a class="header-anchor" href="#cross-platform-ui-i18n-theme-acceptance-criteria" aria-label="Permalink to &quot;Cross-Platform UI, i18n &amp; Theme Acceptance Criteria&quot;">​</a></h2><ul><li><strong>Endpoints &amp; Implementation:</strong> <code>PUT /api/v1/agencies/{agencyId} · POST /api/v1/agencies/{agencyId}/logo · POST /api/v1/agencies/{agencyId}/banner</code> (<code>AgencyController.updateAgency() / uploadLogo() / uploadBanner()</code> -&gt; <code>AgencyServiceImpl.updateAgency() / uploadLogo() / uploadBanner(), S3FileStorageServiceImpl</code>). Strictly enforces <code>agency.ownerId.equals(currentUser.id)</code> (<code>BR-15</code>), updates metadata fields (<code>name</code>, <code>description</code>, <code>website</code>, <code>industry</code>, <code>companyType</code>, <code>companySize</code>, <code>taxCode</code>, <code>address</code>, <code>phone</code>, <code>contactEmail</code>), and handles validated S3 logo/banner uploads.</li><li><strong>Internationalization (<code>vi</code> / <code>en</code>):</strong> All labels, buttons, empty states, and error/confirmation toasts use key-parallel locale entries (<code>agency.detail.* / agency.edit.*</code>) in both <code>vi</code> and <code>en</code> bundles — zero hardcoded UI text.</li><li><strong>Semantic Light/Dark Theme:</strong> Web (<code>src/pages/agency/detail.tsx</code>, <code>src/pages/agency/components/{AgencyDetailEditForm,AgencyDetailLivePreview,AgencyBrandingSection}.tsx</code>, <code>src/components/shared/BannerUploader.tsx</code>) and Mobile (<code>src/services/agencyService.ts</code>) surfaces use semantic theme tokens with WCAG-compliant contrast in both Light and Dark modes.</li><li><strong>Related Documentation:</strong> <a href="./../../../../ba/03-agency-workspace.html">BA Agency &amp; Workspace Spec</a> · <a href="./../../../../ba/README.html">BA Overview</a> · <a href="./../../../modules/README.html">Module Specs Index</a> · <a href="./test.html">Test Suite</a>.</li></ul>',26)])])}const p=t(n,[["render",l]]);export{g as __pageData,p as default};
